script:
frappe.ui.form.on('Stock Entry', {
	farm: function(frm) {
		// Filter warehouses by farm when farm is selected
		if (frm.doc.farm) {
			// Set filters for from_warehouse and to_warehouse
			frm.set_query('from_warehouse', function() {
				return {
					filters: {
						'warehouse_name': ['like', '%' + frm.doc.farm + '%']
					}
				};
			});

			frm.set_query('to_warehouse', function() {
				return {
					filters: {
						'warehouse_name': ['like', '%' + frm.doc.farm + '%']
					}
				};
			});
		}
	},

	field: function(frm) {
		// Auto-populate farm from field
		if (frm.doc.field && !frm.doc.farm) {
			frappe.db.get_value('Field', frm.doc.field, 'farm', (r) => {
				if (r && r.farm) {
					frm.set_value('farm', r.farm);
				}
			});
		}
	}
});
